package com.ryanjei.orushio.pve.paper;import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.map.*;import java.util.*;import org.junit.jupiter.api.Test;
class SetupMarkerOwnershipTest{@Test void PDCへ書くownership値はMarker種別SessionMap管理者を含む(){UUID marker=UUID.randomUUID(),admin=UUID.randomUUID();var token=new MapWorldGateway.SetupMarkerToken(marker,SetupMarkerType.NORMAL_ENEMY_SPAWN,"session-a","map-a",admin);Map<String,String>values=PaperMapWorldGateway.markerMetadata(token);assertEquals(marker.toString(),values.get("markerId"));assertEquals("NORMAL_ENEMY_SPAWN",values.get("markerType"));assertEquals("session-a",values.get("sessionId"));assertEquals("map-a",values.get("mapId"));assertEquals(admin.toString(),values.get("administrator"));}}
